import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';

const AdminDashboard = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('overview');

  const handleLogout = () => {
    logout();
    navigate('/admin-signin');
  };

  if (!user || user.role !== 'admin') {
    return (
      <div className="min-h-screen bg-gradient-to-br from-red-50 to-orange-50 flex items-center justify-center">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-red-600 mb-4">Access Denied</h2>
          <p className="text-gray-600 mb-6">You must be logged in as an admin to access this page.</p>
          <button
            onClick={() => navigate('/admin-signin')}
            className="bg-red-500 hover:bg-red-600 text-white font-bold py-2 px-6 rounded-lg"
          >
            Go to Admin Login
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-red-50 via-white to-orange-50">
      {/* Header */}
      <header className="bg-white shadow-lg">
        <div className="max-w-7xl mx-auto px-4 py-6 flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-bold bg-gradient-to-r from-red-900 to-orange-800 bg-clip-text text-transparent">
              Admin Dashboard
            </h1>
            {user.templeCity && (
              <p className="text-gray-600 text-sm">Temple: {user.templeCity}</p>
            )}
          </div>
          <div className="flex items-center gap-4">
            <div className="text-right">
              <p className="font-semibold text-gray-800">{user.fullName}</p>
              <p className="text-sm text-gray-500">{user.email}</p>
            </div>
            <button
              onClick={handleLogout}
              className="bg-red-500 hover:bg-red-600 text-white font-bold py-2 px-4 rounded-lg transition-all"
            >
              Logout
            </button>
          </div>
        </div>
      </header>

      {/* Navigation Tabs */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex gap-8">
            <button
              onClick={() => setActiveTab('overview')}
              className={`py-4 px-2 font-semibold border-b-2 transition-all ${
                activeTab === 'overview'
                  ? 'border-red-500 text-red-600'
                  : 'border-transparent text-gray-600 hover:text-gray-900'
              }`}
            >
              Overview
            </button>
            <button
              onClick={() => setActiveTab('queue')}
              className={`py-4 px-2 font-semibold border-b-2 transition-all ${
                activeTab === 'queue'
                  ? 'border-red-500 text-red-600'
                  : 'border-transparent text-gray-600 hover:text-gray-900'
              }`}
            >
              Virtual Queue
            </button>
            <button
              onClick={() => setActiveTab('devotees')}
              className={`py-4 px-2 font-semibold border-b-2 transition-all ${
                activeTab === 'devotees'
                  ? 'border-red-500 text-red-600'
                  : 'border-transparent text-gray-600 hover:text-gray-900'
              }`}
            >
              Devotees
            </button>
            <button
              onClick={() => setActiveTab('reports')}
              className={`py-4 px-2 font-semibold border-b-2 transition-all ${
                activeTab === 'reports'
                  ? 'border-red-500 text-red-600'
                  : 'border-transparent text-gray-600 hover:text-gray-900'
              }`}
            >
              Reports
            </button>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 py-12">
        {/* Overview Tab */}
        {activeTab === 'overview' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              {/* Stats Cards */}
              <div className="bg-white rounded-2xl shadow-lg p-6 border-l-4 border-red-500">
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-gray-600 text-sm font-semibold">Total Devotees</p>
                    <p className="text-3xl font-bold text-gray-900 mt-2">1,234</p>
                  </div>
                  <span className="text-3xl">👥</span>
                </div>
              </div>

              <div className="bg-white rounded-2xl shadow-lg p-6 border-l-4 border-orange-500">
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-gray-600 text-sm font-semibold">Queue Length</p>
                    <p className="text-3xl font-bold text-gray-900 mt-2">45</p>
                  </div>
                  <span className="text-3xl">⏱️</span>
                </div>
              </div>

              <div className="bg-white rounded-2xl shadow-lg p-6 border-l-4 border-yellow-500">
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-gray-600 text-sm font-semibold">Avg Wait Time</p>
                    <p className="text-3xl font-bold text-gray-900 mt-2">32 min</p>
                  </div>
                  <span className="text-3xl">⏳</span>
                </div>
              </div>

              <div className="bg-white rounded-2xl shadow-lg p-6 border-l-4 border-green-500">
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-gray-600 text-sm font-semibold">Served Today</p>
                    <p className="text-3xl font-bold text-gray-900 mt-2">287</p>
                  </div>
                  <span className="text-3xl">✅</span>
                </div>
              </div>
            </div>

            {/* Recent Activity */}
            <div className="bg-white rounded-2xl shadow-lg p-6">
              <h3 className="text-xl font-bold text-gray-900 mb-4">Recent Activity</h3>
              <div className="space-y-4">
                {[1, 2, 3, 4, 5].map((item) => (
                  <div key={item} className="flex items-center gap-4 p-4 bg-gray-50 rounded-xl">
                    <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                    <div className="flex-1">
                      <p className="font-semibold text-gray-900">Devotee {item} checked in</p>
                      <p className="text-sm text-gray-500">5 minutes ago</p>
                    </div>
                    <span className="text-gray-400">→</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Virtual Queue Tab */}
        {activeTab === 'queue' && (
          <div className="bg-white rounded-2xl shadow-lg p-8">
            <h3 className="text-2xl font-bold text-gray-900 mb-6">Virtual Queue Management</h3>
            <div className="bg-blue-50 border-2 border-blue-200 rounded-2xl p-8 text-center">
              <p className="text-gray-600 text-lg">Queue management features coming soon...</p>
            </div>
          </div>
        )}

        {/* Devotees Tab */}
        {activeTab === 'devotees' && (
          <div className="bg-white rounded-2xl shadow-lg p-8">
            <h3 className="text-2xl font-bold text-gray-900 mb-6">Devotees Management</h3>
            <div className="bg-blue-50 border-2 border-blue-200 rounded-2xl p-8 text-center">
              <p className="text-gray-600 text-lg">Devotees management features coming soon...</p>
            </div>
          </div>
        )}

        {/* Reports Tab */}
        {activeTab === 'reports' && (
          <div className="bg-white rounded-2xl shadow-lg p-8">
            <h3 className="text-2xl font-bold text-gray-900 mb-6">Reports & Analytics</h3>
            <div className="bg-blue-50 border-2 border-blue-200 rounded-2xl p-8 text-center">
              <p className="text-gray-600 text-lg">Reports and analytics features coming soon...</p>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default AdminDashboard;
